BEGIN;
ALTER TABLE "User" ADD COLUMN "phoneNumber" VARCHAR(16), ADD COLUMN "dateOfBirth" DATE, ADD COLUMN "location" VARCHAR(100);
CREATE TABLE "LinkPreview" (id UUID PRIMARY KEY, url VARCHAR(2048) NOT NULL UNIQUE,title VARCHAR(300) NOT NULL,description VARCHAR(600) NOT NULL,"siteName" VARCHAR(100) NOT NULL,"imageBytes" BYTEA,"imageWidth" INTEGER,"imageHeight" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "Post" ADD COLUMN "quotedPostId" UUID, ADD COLUMN "linkPreviewId" UUID;
ALTER TABLE "Post" ADD CONSTRAINT "Post_quotedPostId_fkey" FOREIGN KEY ("quotedPostId") REFERENCES "Post"(id) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Post" ADD CONSTRAINT "Post_linkPreviewId_fkey" FOREIGN KEY ("linkPreviewId") REFERENCES "LinkPreview"(id) ON DELETE SET NULL ON UPDATE CASCADE;
CREATE INDEX "Post_quotedPostId_idx" ON "Post"("quotedPostId");
CREATE INDEX "Post_linkPreviewId_idx" ON "Post"("linkPreviewId");
CREATE TABLE "FeedEvent" (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),"postId" UUID NOT NULL REFERENCES "Post"(id) ON DELETE CASCADE ON UPDATE CASCADE,"actorId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,kind VARCHAR(10) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "FeedEvent_postId_actorId_kind_key" ON "FeedEvent"("postId","actorId",kind);
CREATE INDEX "FeedEvent_createdAt_id_idx" ON "FeedEvent"("createdAt" DESC,id DESC);
CREATE INDEX "FeedEvent_actorId_createdAt_idx" ON "FeedEvent"("actorId","createdAt" DESC);
INSERT INTO "FeedEvent" ("postId","actorId",kind,"createdAt") SELECT id,"authorId",'POST',"createdAt" FROM "Post" WHERE "parentId" IS NULL;
INSERT INTO "FeedEvent" ("postId","actorId",kind,"createdAt") SELECT "postId","userId",'REPOST',"createdAt" FROM "Repost";
CREATE FUNCTION fpi_post_feed() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN IF NEW."parentId" IS NULL THEN INSERT INTO "FeedEvent" ("postId","actorId",kind,"createdAt") VALUES (NEW.id,NEW."authorId",'POST',NEW."createdAt"); END IF; RETURN NEW; END $$;
CREATE TRIGGER fpi_post_feed AFTER INSERT ON "Post" FOR EACH ROW EXECUTE FUNCTION fpi_post_feed();
CREATE FUNCTION fpi_repost_feed() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO "FeedEvent" ("postId","actorId",kind,"createdAt") VALUES (NEW."postId",NEW."userId",'REPOST',NEW."createdAt") ON CONFLICT DO NOTHING; RETURN NEW; ELSE DELETE FROM "FeedEvent" WHERE "postId"=OLD."postId" AND "actorId"=OLD."userId" AND kind='REPOST'; RETURN OLD; END IF; END $$;
CREATE TRIGGER fpi_repost_feed AFTER INSERT OR DELETE ON "Repost" FOR EACH ROW EXECUTE FUNCTION fpi_repost_feed();
COMMIT;
